import sys
import sqlite3
import json
import os

def parse_input():
    conditions = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split('=', 1)
        if len(parts) != 2:
            continue
        key, value = parts
        conditions[key] = value
    return conditions

def query_database(db_path, conditions):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    query = "SELECT id, name, email, city FROM contacts ORDER BY id ASC"
    params = []
    placeholders = []
    for col in ['name', 'email', 'city']:
        if col in conditions:
            placeholders.append(f"?")
            params.append(conditions[col])
    if placeholders:
        query += " WHERE "
        query += " AND ".join([f"{col} = ?" for col in ['name', 'email', 'city'] if col in conditions])
        cursor.execute(query, params)
    else:
        cursor.execute(query)
    rows = cursor.fetchall()
    conn.close()
    return rows

def load_cache(db_path):
    cache_path = f"{db_path}.cache"
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            return json.load(f)
    return None

def save_cache(db_path, data):
    cache_path = f"{db_path}.cache"
    with open(cache_path, 'w') as f:
        json.dump(data, f)

def main():
    if len(sys.argv) != 2:
        print("Usage: python contact_find.py <database_path>", file=sys.stderr)
        sys.exit(1)

    db_path = sys.argv[1]
    conditions = parse_input()

    cache = load_cache(db_path)
    if cache is not None:
        for row in cache:
            print(json.dumps({
                'id': row[0],
                'name': row[1],
                'email': row[2],
                'city': row[3]
            }))
        return

    rows = query_database(db_path, conditions)
    cache_data = [{"id": row[0], "name": row[1], "email": row[2], "city": row[3]} for row in rows]
    save_cache(db_path, cache_data)

    for row in cache_data:
        print(json.dumps({
            'id': row['id'],
            'name': row['name'],
            'email': row['email'],
            'city': row['city']
        }))

if __name__ == "__main__":
    main()
